))track(hopModeButton.MouseButton1Click:Connect(function()serverHopMode=serverHopMode=="Random"and"Smallest"or"Random"refreshButtons()refreshStatus("Server hop mode: "..serverHopMode)end))track(teamPrefButton.MouseButton1Click:Connect(function()nextJoinTeam=nextJoinTeam=="Marines"and"Pirates"or"Marines"saveNextJoinTeam()refreshButtons()refreshStatus("Next join team saved: "..(nextJoinTeam=="Marines"and"Marine"or"Pirate")..". Your current team will not change.")end))controller.GetStoreFruitRemote=function()
    local remotes=ReplicatedStorage:FindFirstChild("Remotes")
    local remote=remotes and remotes:FindFirstChild("CommF_")
    if remote and remote:IsA("RemoteFunction") then return remote end
