controller.IsStoreFruitTool=function(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local originalName=nil
    pcall(function() originalName=tool:GetAttribute("OriginalName") end)
    local toolTip=""
    pcall(function() toolTip=tool.ToolTip end)
    if toolTip=="Blox Fruit" then return true end
    if type(originalName)=="string" and originalName~="" then
        if getKnownFruitDisplayNameFromObjectName(originalName) or string.find(originalName,"Fruit",1,true) then return true end
    end
    if getKnownFruitDisplayNameFromObjectName(tool.Name) then return true end
    return string.find(tool.Name,"Fruit",1,true)~=nil
end
controller.GetStoreFruitName=function(tool)
    local originalName=nil
    pcall(function() originalName=tool:GetAttribute("OriginalName") end)
    if type(originalName)=="string" and originalName~="" then return originalName end
    local rawName=tool.Name
    local prefix=rawName:match("^(.-)%-")
    if prefix and prefix~="" then return prefix end
    local known=getKnownFruitDisplayNameFromObjectName(rawName)
    if known then return known end
    return rawName:gsub("%s+[Ff]ruit$","")
end
controller.ConnectStoreEvent=function()
    local remotes=ReplicatedStorage:FindFirstChild("Remotes")
    local event=remotes and remotes:FindFirstChild("CommE")
    if event and event:IsA("RemoteEvent") then
        track(event.OnClientEvent:Connect(function(eventName,item,eventState)
            if eventName=="ItemChanged" and eventState=="stored" and item then
                local itemName=typeof(item)=="Instance" and item.Name or (type(item)=="table" and tostring(item.Name or "") or tostring(item))
                local confirmedAt=os.clock()
                local confirmations=controller.StoreState.Confirmations
                confirmations[canonicalFruitName(itemName)]=confirmedAt
                local knownName=getKnownFruitDisplayNameFromObjectName(itemName)
                if knownName then confirmations[canonicalFruitName(knownName)]=confirmedAt end
                local prefix=itemName:match("^(.-)%-")
                if prefix and prefix~="" then confirmations[canonicalFruitName(prefix)]=confirmedAt end
            end
        end))
    else
        warn("[BerryFruitHunter] Auto Store: CommE confirmation event not found; tool removal/remote response will be used instead.")
    end
end
controller.ConnectStoreEvent()
controller.RunAutoStoreFruit=function()
    local state=controller.StoreState
    if not running or not autoStoreEnabled or state.Busy then return end
    state.Busy=true
    local ok,err=pcall(function()
        local remote=controller.GetStoreFruitRemote()
        if not remote then refreshStatus("Auto Store: CommF_ remote not ready") return end
        local backpack=LocalPlayer:FindFirstChildOfClass("Backpack")
        local character=LocalPlayer.Character
        local characters=Workspace:FindFirstChild("Characters")
        local replicatedCharacter=characters and characters:FindFirstChild(LocalPlayer.Name)
        local containers={backpack,character,replicatedCharacter}
        for _,container in ipairs(containers) do
            if container then
                for _,tool in ipairs(container:GetChildren()) do
                    if controller.IsStoreFruitTool(tool) and not state.Done[tool] then
                        local fruitName=controller.GetStoreFruitName(tool)
                        if fruitName and fruitName~="" then
                            local lastAttempt=state.LastAttempt[tool] or 0
                            if os.clock()-lastAttempt>=8 then
                                local confirmations=state.Confirmations
                                confirmations[canonicalFruitName(fruitName)]=nil
                                local normalizedName=getKnownFruitDisplayNameFromObjectName(fruitName)
                                if normalizedName then confirmations[canonicalFruitName(normalizedName)]=nil end
                                local attemptStarted=os.clock()
                                local invokeOk,result=pcall(function()
                                    return remote:InvokeServer("StoreFruit",fruitName,tool)
                                end)
                                task.wait(0.3)
                                local stillInGame=false
                                pcall(function() stillInGame=tool.Parent~=nil and tool:IsDescendantOf(game) end)
                                local confirmationTime=confirmations[canonicalFruitName(fruitName)] or 0
                                if normalizedName then confirmationTime=math.max(confirmationTime,confirmations[canonicalFruitName(normalizedName)] or 0) end
                                local eventConfirmed=confirmationTime>=attemptStarted
                                if invokeOk and (not stillInGame or result==true or eventConfirmed) then
                                    state.LastAttempt[tool]=nil
                                    state.Done[tool]=true
                                    refreshStatus("Auto Store confirmed: "..tostring(fruitName))
                                else
                                    state.LastAttempt[tool]=os.clock()
                                    if not invokeOk then refreshStatus("Auto Store error: "..tostring(result))
                                    else refreshStatus("Auto Store pending: "..tostring(fruitName).." | retry in 8s") end
                                end
                                return
                            end
                        end
                    end
                end
            end
        end
    end)
    state.Busy=false
    if not ok then warn("[BerryFruitHunter] Auto Store failed: "..tostring(err)) end
end
controller.TryAutoPickupBerry=function()
    local state=controller.BerryPickupState
    if not running or not controller.BerryPickupEnabled or state.Busy then return end
    local root=getCharacterRoot()
    if not root or not root.Parent then return end
    local now=os.clock()
    local bestPrompt=nil
    local bestName=nil
    local bestDistance=math.huge
    local bestHold=0
    for _,item in pairs(trackedItems) do
        local prompt=item and item.Category=="Berry" and item.Prompt
        if prompt and prompt.Parent and prompt:IsA("ProximityPrompt") and prompt.Enabled and prompt:IsDescendantOf(Workspace) then
            local promptParent=prompt.Parent
            local hostPart=promptParent:IsA("BasePart") and promptParent or promptParent:FindFirstAncestorWhichIsA("BasePart")
            if hostPart then
                local promptPosition=hostPart.Position
                if promptParent:IsA("Attachment") then promptPosition=promptParent.WorldPosition end
                local maxDistance=tonumber(prompt.MaxActivationDistance) or 0
                local distance=(root.Position-promptPosition).Magnitude
                local lastPrompt=state.LastPrompt[prompt] or 0
                if maxDistance>0 and distance<=maxDistance and distance<bestDistance and now-lastPrompt>=1.25 then
                    bestPrompt=prompt
                    bestName=item.Name or "Berry"
                    bestDistance=distance
                    bestHold=math.max(tonumber(prompt.HoldDuration) or 0,0)
                end
            end
        end
    end
    if not bestPrompt then return end
    state.Busy=true
    state.ActivePrompt=bestPrompt
    state.LastPrompt[bestPrompt]=now
    local began=pcall(function() bestPrompt:InputHoldBegin() end)
    if not began then
        local firePrompt=envFunction("fireproximityprompt")
        if firePrompt then began=pcall(firePrompt,bestPrompt,bestHold) end
    end
    if not began then
        state.Busy=false
        state.ActivePrompt=nil
        refreshStatus("Auto Pick Berry: prompt input unavailable")
        return
    end
    task.delay(math.max(bestHold,0.06),function()
        if bestPrompt and bestPrompt.Parent then pcall(function() bestPrompt:InputHoldEnd() end) end
        state.ActivePrompt=nil
        state.Busy=false
        if running then refreshStatus("Auto Pick Berry interacted: "..tostring(bestName)) end
    end)
end
